      )}

      {/* Admin: Pending Approvals */}
      {isAdmin && pendingTimesheets.length > 0 && (
        <div className="mb-6 bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-bold text-gray-900 mb-4">
            Pending Approvals ({pendingTimesheets.length})
